tarjan(u, parent):
  dfn[u] = low[u] = ++timer
  child_count = 0
  for v in adj[u]:
    if not visited[v]:
      child_count += 1
      tarjan(v, u)
      low[u] = min(low[u], low[v])
      if parent != root and low[v] >= dfn[u]:
        is_cut[u] = True
      # 根节点判断在循环外: if parent==root and child_count>=2: is_cut[u]=True
    elif v != parent:
      low[u] = min(low[u], dfn[v])
